CREATE EXTENSION IF NOT EXISTS vector;
CREATE TABLE IF NOT EXISTS model_registry(model_version text PRIMARY KEY, model_name text NOT NULL, checkpoint_sha256 text, code_commit text, config_hash text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS cows(cow_uuid uuid PRIMARY KEY, display_id text UNIQUE NOT NULL, identity_state text NOT NULL CHECK(identity_state IN ('provisional','visual_confirmed','stable_visual','external_linked','ambiguous','retired')), external_id text, created_at timestamptz NOT NULL DEFAULT now(), retired_at timestamptz);
CREATE TABLE IF NOT EXISTS cow_aliases(alias text PRIMARY KEY, cow_uuid uuid NOT NULL REFERENCES cows, valid_from timestamptz NOT NULL DEFAULT now(), valid_to timestamptz, reason text);
CREATE TABLE IF NOT EXISTS sessions(session_uuid uuid PRIMARY KEY, camera_id text NOT NULL, recording_date date NOT NULL, session_type text, domain text, start_at timestamptz, end_at timestamptz, UNIQUE(camera_id,recording_date,session_type,domain));
CREATE TABLE IF NOT EXISTS videos(video_uuid text PRIMARY KEY, sha256 text UNIQUE NOT NULL, perceptual_fingerprint text, camera_id text NOT NULL, recording_start timestamptz, recording_end timestamptz, timestamp_source text NOT NULL, timestamp_confidence double precision, ocr_samples_json jsonb NOT NULL DEFAULT '[]', canonical_video_uuid text, overlap_group_id text, media_uri text NOT NULL, status text NOT NULL DEFAULT 'INGESTED', attempt_count integer NOT NULL DEFAULT 0, last_error text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS tracklets(tracklet_uuid text PRIMARY KEY, video_uuid text NOT NULL REFERENCES videos, session_uuid uuid REFERENCES sessions, cow_uuid uuid REFERENCES cows, start_s double precision NOT NULL, end_s double precision NOT NULL, direction text, flank text, quality_score double precision, review_state text, metadata_json jsonb NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS reid_embeddings(embedding_uuid uuid PRIMARY KEY, tracklet_uuid text NOT NULL REFERENCES tracklets, model_version text NOT NULL REFERENCES model_registry, embedding vector(128) NOT NULL, dimensions integer NOT NULL DEFAULT 128, quality_score double precision, UNIQUE(tracklet_uuid,model_version));
CREATE INDEX IF NOT EXISTS reid_embeddings_cosine ON reid_embeddings USING hnsw (embedding vector_cosine_ops);
CREATE TABLE IF NOT EXISTS identity_edges(edge_uuid uuid PRIMARY KEY, left_entity text NOT NULL, right_entity text NOT NULL, decision text NOT NULL, reviewer text, similarity double precision, created_at timestamptz NOT NULL DEFAULT now(), superseded_by uuid);
CREATE TABLE IF NOT EXISTS identity_audit(audit_uuid uuid PRIMARY KEY, operation text NOT NULL, payload_json jsonb NOT NULL, inverse_json jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), undone_at timestamptz);
CREATE TABLE IF NOT EXISTS keypoint_runs(run_uuid uuid PRIMARY KEY, tracklet_uuid text NOT NULL REFERENCES tracklets, model_version text NOT NULL, status text NOT NULL, raw_output_uri text, quality_summary_json jsonb, attempt_count integer NOT NULL DEFAULT 0, last_error text, UNIQUE(tracklet_uuid,model_version));
CREATE TABLE IF NOT EXISTS posture_observations(observation_uuid uuid PRIMARY KEY, tracklet_uuid text NOT NULL REFERENCES tracklets, feature_name text NOT NULL, value double precision NOT NULL, uncertainty double precision, valid_frame_ratio double precision, model_version text NOT NULL, observed_at timestamptz NOT NULL, UNIQUE(tracklet_uuid,feature_name,model_version));
CREATE TABLE IF NOT EXISTS health_summaries(cow_uuid uuid NOT NULL REFERENCES cows, period_start timestamptz NOT NULL, period_end timestamptz NOT NULL, feature_name text NOT NULL, median_value double precision, baseline double precision, delta double precision, robust_z double precision, status text NOT NULL, algorithm_version text NOT NULL, PRIMARY KEY(cow_uuid,period_end,feature_name,algorithm_version));
